    /// <para>
    /// If the subclass wishes to copy over existing fields (like pixel aspec ratio,
    /// or framerate) from an existing #GstVideoCodecState, it can be provided as a
    /// @reference.
    /// </para>
    /// <para>
    /// If the subclass wishes to override some fields from the output state (like
    /// pixel-aspect-ratio or framerate) it can do so on the returned #GstVideoCodecState.
    /// </para>
    /// <para>
    /// The new output state will only take effect (set on pads and buffers) starting
    /// from the next call to #gst_video_decoder_finish_frame().
    /// </para>
    /// </remarks>
    /// <param name="fmt">The <c>fmt</c> argument.</param>
    /// <param name="width">The <c>width</c> argument.</param>
    /// <param name="height">The <c>height</c> argument.</param>
    /// <param name="reference">The <c>reference</c> argument.</param>
    /// <returns>the newly configured output state.</returns>
    public Gst.Video.VideoCodecState? SetOutputState(Gst.Video.VideoFormat fmt, uint width, uint height, Gst.Video.VideoCodecState? reference)
    {
        nint nativeResult = GstVideoDecoderSetOutputState(Handle, (int)fmt, width, height, reference is null ? 0 : reference.Handle);
        System.GC.KeepAlive(this);
        System.GC.KeepAlive(reference);
        return Gst.Video.VideoCodecState.FromNative(nativeResult, Gst.Interop.Transfer.Full);
    }

    /// <summary>
    /// Allows baseclass to consider input data as packetized or not. If the
    /// input is packetized, then the @parse method will not be called.
    /// </summary>
    /// <param name="packetized">The <c>packetized</c> argument.</param>
    public void SetPacketized(bool packetized)
    {
        GstVideoDecoderSetPacketized(Handle, packetized ? 1 : 0);
        System.GC.KeepAlive(this);
    }

    /// <summary>
    /// If this is set to TRUE, it informs the base class that the subclass
    /// can receive the data at a granularity lower than one frame.
    /// </summary>
    /// <remarks>
    /// <para>
    /// Note that in this mode, the subclass has two options. It can either
    /// require the presence of a GST_VIDEO_BUFFER_FLAG_MARKER to mark the
    /// end of a frame. Or it can operate in such a way that it will decode
    /// a single frame at a time. In this second case, every buffer that
    /// arrives to the element is considered part of the same frame until
    /// gst_video_decoder_finish_frame() is called.
    /// </para>
    /// <para>
    /// In either case, the same #GstVideoCodecFrame will be passed to the
    /// GstVideoDecoderClass:handle_frame vmethod repeatedly with a
    /// different GstVideoCodecFrame:input_buffer every time until the end of the
    /// frame has been signaled using either method.
    /// This method must be called during the decoder subclass @set_format call.
    /// </para>
    /// </remarks>
    /// <param name="subframeMode">The <c>subframeMode</c> argument.</param>
    public void SetSubframeMode(bool subframeMode)
    {
        GstVideoDecoderSetSubframeMode(Handle, subframeMode ? 1 : 0);
        System.GC.KeepAlive(this);
    }

    /// <summary>
    /// Lets #GstVideoDecoder sub-classes decide if they want the sink pad
    /// to use the default pad query handler to reply to accept-caps queries.
    /// </summary>
    /// <remarks>
    /// <para>
    /// By setting this to true it is possible to further customize the default
    /// handler with %GST_PAD_SET_ACCEPT_INTERSECT and
    /// %GST_PAD_SET_ACCEPT_TEMPLATE
    /// </para>
    /// </remarks>
    /// <param name="use">The <c>use</c> argument.</param>
    public void SetUseDefaultPadAcceptcaps(bool use)
    {
        GstVideoDecoderSetUseDefaultPadAcceptcaps(Handle, use ? 1 : 0);
        System.GC.KeepAlive(this);
    }

